mapper.select:
select
    (
        select count(distinct f.elderly_id)
        from biz_elderly_family f
        where f.user_id = #{userId}
    ) as elderlyTotal,
    (
        select count(*)
        from biz_alert_record ar
        where ar.elderly_id in (
            select distinct f.elderly_id
            from biz_elderly_family f
            where f.user_id = #{userId}
        )
          and date(ar.create_time) = curdate()
    ) as todayAlertTotal,
    (
        select count(*)
        from biz_alert_record ar
        where ar.elderly_id in (
            select distinct f.elderly_id
            from biz_elderly_family f
            where f.user_id = #{userId}
        )
          and ar.alert_level = 2
          and ar.handle_status in ('0', '1')
    ) as urgentAlertTotal,
    (
        select count(*)
        from biz_health_report hr
        where hr.elderly_id in (
            select distinct f.elderly_id
            from biz_elderly_family f
            where f.user_id = #{userId}
        )
          and hr.report_date >= date_sub(curdate(), interval 7 day)
    ) as weekReportTotal,
    (
        select count(*)
        from biz_elderly_family f
        where f.user_id = #{userId}
          and f.is_emergency in ('1', 'Y')
    ) as emergencyContactTotal
